macro_rules! channel_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function channel in module {}", module_path!());
    };
}

mkfn!{
    channel_introspect!();
    # [doc = " Creates a new asynchronous channel, returning the sender/receiver halves."] # [doc = ""] # [doc = " All data sent on the [`Sender`] will become available on the [`Receiver`] in"] # [doc = " the same order as it was sent, and no [`send`] will block the calling thread"] # [doc = " (this channel has an \"infinite buffer\", unlike [`sync_channel`], which will"] # [doc = " block after its buffer limit is reached). [`recv`] will block until a message"] # [doc = " is available while there is at least one [`Sender`] alive (including clones)."] # [doc = ""] # [doc = " The [`Sender`] can be cloned to [`send`] to the same channel multiple times, but"] # [doc = " only one [`Receiver`] is supported."] # [doc = ""] # [doc = " If the [`Receiver`] is disconnected while trying to [`send`] with the"] # [doc = " [`Sender`], the [`send`] method will return a [`SendError`]. Similarly, if the"] # [doc = " [`Sender`] is disconnected while trying to [`recv`], the [`recv`] method will"] # [doc = " return a [`RecvError`]."] # [doc = ""] # [doc = " [`send`]: Sender::send"] # [doc = " [`recv`]: Receiver::recv"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::sync::mpsc::channel;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " let (sender, receiver) = channel();"] # [doc = ""] # [doc = " // Spawn off an expensive computation"] # [doc = " thread::spawn(move || {"] # [doc = " #   fn expensive_computation() {}"] # [doc = "     sender.send(expensive_computation()).unwrap();"] # [doc = " });"] # [doc = ""] # [doc = " // Do some useful work for a while"] # [doc = ""] # [doc = " // Let's see what that answer was"] # [doc = " println!(\"{:?}\", receiver.recv().unwrap());"] # [doc = " ```"] # [must_use] # [stable (feature = "rust1" , since = "1.0.0")] pub fn channel < T > () -> (Sender < T > , Receiver < T >) { let (tx , rx) = mpmc :: channel () ; (Sender { inner : tx } , Receiver { inner : rx }) }
}

macro_rules! sync_channel_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function sync_channel in module {}", module_path!());
    };
}

mkfn!{
    sync_channel_introspect!();
    # [doc = " Creates a new synchronous, bounded channel."] # [doc = ""] # [doc = " All data sent on the [`SyncSender`] will become available on the [`Receiver`]"] # [doc = " in the same order as it was sent. Like asynchronous [`channel`]s, the"] # [doc = " [`Receiver`] will block until a message becomes available. `sync_channel`"] # [doc = " differs greatly in the semantics of the sender, however."] # [doc = ""] # [doc = " This channel has an internal buffer on which messages will be queued."] # [doc = " `bound` specifies the buffer size. When the internal buffer becomes full,"] # [doc = " future sends will *block* waiting for the buffer to open up. Note that a"] # [doc = " buffer size of 0 is valid, in which case this becomes \"rendezvous channel\""] # [doc = " where each [`send`] will not return until a [`recv`] is paired with it."] # [doc = ""] # [doc = " The [`SyncSender`] can be cloned to [`send`] to the same channel multiple"] # [doc = " times, but only one [`Receiver`] is supported."] # [doc = ""] # [doc = " Like asynchronous channels, if the [`Receiver`] is disconnected while trying"] # [doc = " to [`send`] with the [`SyncSender`], the [`send`] method will return a"] # [doc = " [`SendError`]. Similarly, If the [`SyncSender`] is disconnected while trying"] # [doc = " to [`recv`], the [`recv`] method will return a [`RecvError`]."] # [doc = ""] # [doc = " [`send`]: SyncSender::send"] # [doc = " [`recv`]: Receiver::recv"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::sync::mpsc::sync_channel;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " let (sender, receiver) = sync_channel(1);"] # [doc = ""] # [doc = " // this returns immediately"] # [doc = " sender.send(1).unwrap();"] # [doc = ""] # [doc = " thread::spawn(move || {"] # [doc = "     // this will block until the previous message has been received"] # [doc = "     sender.send(2).unwrap();"] # [doc = " });"] # [doc = ""] # [doc = " assert_eq!(receiver.recv().unwrap(), 1);"] # [doc = " assert_eq!(receiver.recv().unwrap(), 2);"] # [doc = " ```"] # [must_use] # [stable (feature = "rust1" , since = "1.0.0")] pub fn sync_channel < T > (bound : usize) -> (SyncSender < T > , Receiver < T >) { let (tx , rx) = mpmc :: sync_channel (bound) ; (SyncSender { inner : tx } , Receiver { inner : rx }) }
}
