mkitem!{mkimpl!{impl < T > SyncSender < T > { # [doc = " Sends a value on this synchronous channel."] # [doc = ""] # [doc = " This function will *block* until space in the internal buffer becomes"] # [doc = " available or a receiver is available to hand off the message to."] # [doc = ""] # [doc = " Note that a successful send does *not* guarantee that the receiver will"] # [doc = " ever see the data if there is a buffer on this channel. Items may be"] # [doc = " enqueued in the internal buffer for the receiver to receive at a later"] # [doc = " time. If the buffer size is 0, however, the channel becomes a rendezvous"] # [doc = " channel and it guarantees that the receiver has indeed received"] # [doc = " the data if this function returns success."] # [doc = ""] # [doc = " This function will never panic, but it may return [`Err`] if the"] # [doc = " [`Receiver`] has disconnected and is no longer able to receive"] # [doc = " information."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " use std::sync::mpsc::sync_channel;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " // Create a rendezvous sync_channel with buffer size 0"] # [doc = " let (sync_sender, receiver) = sync_channel(0);"] # [doc = ""] # [doc = " thread::spawn(move || {"] # [doc = "    println!(\"sending message...\");"] # [doc = "    sync_sender.send(1).unwrap();"] # [doc = "    // Thread is now blocked until the message is received"] # [doc = ""] # [doc = "    println!(\"...message received!\");"] # [doc = " });"] # [doc = ""] # [doc = " let msg = receiver.recv().unwrap();"] # [doc = " assert_eq!(1, msg);"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] pub fn send (& self , t : T) -> Result < () , SendError < T > > { self . inner . send (t) } # [doc = " Attempts to send a value on this channel without blocking."] # [doc = ""] # [doc = " This method differs from [`send`] by returning immediately if the"] # [doc = " channel's buffer is full or no receiver is waiting to acquire some"] # [doc = " data. Compared with [`send`], this function has two failure cases"] # [doc = " instead of one (one for disconnection, one for a full buffer)."] # [doc = ""] # [doc = " See [`send`] for notes about guarantees of whether the"] # [doc = " receiver has received the data or not if this function is successful."] # [doc = ""] # [doc = " [`send`]: Self::send"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " use std::sync::mpsc::sync_channel;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " // Create a sync_channel with buffer size 1"] # [doc = " let (sync_sender, receiver) = sync_channel(1);"] # [doc = " let sync_sender2 = sync_sender.clone();"] # [doc = ""] # [doc = " // First thread owns sync_sender"] # [doc = " let handle1 = thread::spawn(move || {"] # [doc = "     sync_sender.send(1).unwrap();"] # [doc = "     sync_sender.send(2).unwrap();"] # [doc = "     // Thread blocked"] # [doc = " });"] # [doc = ""] # [doc = " // Second thread owns sync_sender2"] # [doc = " let handle2 = thread::spawn(move || {"] # [doc = "     // This will return an error and send"] # [doc = "     // no message if the buffer is full"] # [doc = "     let _ = sync_sender2.try_send(3);"] # [doc = " });"] # [doc = ""] # [doc = " let mut msg;"] # [doc = " msg = receiver.recv().unwrap();"] # [doc = " println!(\"message {msg} received\");"] # [doc = ""] # [doc = " msg = receiver.recv().unwrap();"] # [doc = " println!(\"message {msg} received\");"] # [doc = ""] # [doc = " // Third message may have never been sent"] # [doc = " match receiver.try_recv() {"] # [doc = "     Ok(msg) => println!(\"message {msg} received\"),"] # [doc = "     Err(_) => println!(\"the third message was never sent\"),"] # [doc = " }"] # [doc = ""] # [doc = " // Wait for threads to complete"] # [doc = " handle1.join().unwrap();"] # [doc = " handle2.join().unwrap();"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] pub fn try_send (& self , t : T) -> Result < () , TrySendError < T > > { self . inner . try_send (t) } # [unstable (issue = "none" , feature = "std_internals")] # [doc (hidden)] pub fn send_timeout (& self , t : T , timeout : Duration) -> Result < () , mpmc :: SendTimeoutError < T > > { self . inner . send_timeout (t , timeout) } }}}
